// Source-verified rooms share the existing viewer, dialog and reading-position API.
(() => {
  'use strict';
  const data=window.STORY_WORLD,art=window.BookWorld,reader=window.BookReader;
  if(!data||!art||!reader)return;
  const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
  const button=(label,fn,cls='world-button')=>{const b=el('button',cls,label);b.type='button';b.addEventListener('click',fn);return b;};
  function create(f,{onBack,onAtlas,onRead,onNavigate=null,onMemory=null,exteriorSrc=null,sourceLimit=Infinity,initialArea=null}){
    const root=el('section','location-explorer'),limit=Math.min(reader.location().offset,sourceLimit),outside=exteriorSrc||data.visuals[f.id].src,areas=data.locations[f.id].areas.filter(a=>a.unlock<=limit),head=el('header','location-heading'),eyebrow=el('small','',f.name),name=el('h3','','Dış Görünüm'),controls=el('div','location-controls'),surface=el('div','location-surface'),memory=el('section','scene-memory'),status=el('p','location-status'),selector=el('select'),selectLabel=el('label','location-select');
    let current=null,figure=null,busy=false,disposed=false,timer=0,loadTimer=0,pending=null,generation=0,animation=null;
    root.dataset.location=f.id;head.append(eyebrow,name);status.setAttribute('role','status');status.setAttribute('aria-live','polite');memory.setAttribute('aria-label','Okunan sahnenin anısı');selector.setAttribute('aria-label','Keşfedilen odalar ve alanlar');selectLabel.append(el('span','','Keşfedilen alanlar'),selector);
    const exterior=el('option','','Dış Görünüm');exterior.value='';selector.append(exterior);for(const a of areas){const o=el('option','',a.name);o.value=a.id;selector.append(o);}selector.addEventListener('change',()=>go(selector.value));
    const back=button('← Geri',()=>current?go(''):onBack()),atlas=button('Haritaya Dön',onAtlas),enlarge=button('Tam Ekran İncele',()=>window.BookIllustrations?.openSource(current?.src||outside,{title:current?.name||f.name,trigger:enlarge})),read=button('İlgili Bölüm',()=>{if(current)onRead(current.sourceStart);else onRead(f.unlock);});enlarge.setAttribute('aria-haspopup','dialog');controls.append(back,atlas,enlarge,read);const column=el('div','location-stage-column');column.append(surface,controls,selectLabel,status);root.append(head,column,memory);
    function setBusy(value){busy=value;root.setAttribute('aria-busy',String(value));selector.disabled=value;back.disabled=value;surface.querySelectorAll('button').forEach(b=>b.disabled=value);}
    function render(area,preloaded=null){figure?.dispose?.();art.dispose(memory);current=area;selector.value=area?.id||'';name.textContent=area?.name||'Dış Görünüm';name.tabIndex=-1;root.dataset.area=area?.id||'exterior';root.dataset.expanded='false';enlarge.textContent='Tam Ekran İncele';enlarge.setAttribute('aria-haspopup','dialog');surface.replaceChildren();memory.replaceChildren();status.textContent='';
      const src=area?.src||outside;figure=art.viewer(src,area?.name||f.name,{landmark:!area,preloaded});figure.querySelector('.world-fullscreen')?.remove();figure.querySelector('img').classList.add('world-inspect-image');figure.querySelector('figcaption').textContent=area?'Kaynakta doğrulanmış alan · İllüstrasyon':'Şematik keşif noktaları · Mimari kat planı değildir.';
      const image=figure.querySelector('img'),stage=figure.querySelector('.miniature-stage');const ratio=()=>{if(image.naturalWidth)stage.style.aspectRatio=image.naturalWidth+'/'+image.naturalHeight;};image.addEventListener('load',ratio,{once:true});ratio();surface.append(figure);
      if(!area){const layer=el('div','location-hotspots');for(const a of areas){const p=button('',()=>go(a.id),'location-hotspot');p.dataset.area=a.id;p.style.left=a.x+'%';p.style.top=a.y+'%';p.setAttribute('aria-label',a.name);p.title=a.name;p.append(art.icon(a.icon),el('span','',a.name));layer.append(p);}figure.addOverlay(layer);memory.append(el('small','','MEKÂN DOSYASI'),el('h4','',f.name),el('blockquote','',f.quote));if(areas.length){const list=el('div','location-area-list');for(const a of areas){const open=button('',()=>go(a.id),'location-area-card');open.dataset.areaCard=a.id;open.append(art.photo(a.src,a.name),el('span','',a.name));list.append(open);}memory.append(el('h4','','Keşfedilen alanlar'),list);}else status.textContent='İlgili metni okudukça doğrulanmış alanlar burada açılır.';}
      else{memory.append(el('small','',area.chapter.title),el('h4','','Bu alandan bir anı'),el('blockquote','',area.quote));if(area.memorySrc&&area.memorySrc!==src)memory.append(art.photo(area.memorySrc,area.name+' · Okunan sahne'));const people=el('div','scene-people');for(const id of area.characters||[]){const person=data.facts.find(p=>p.id===id&&p.unlock<=limit);if(person)people.append(el('span','',person.name));}if(people.childElementCount)memory.append(people);memory.append(button('İlgili Bölüme Dön',()=>onRead(area.sourceStart)));}
      if(area&&onMemory)memory.append(button('Anı Tiyatrosunu Aç',()=>onMemory(area)));
      if(!area&&data.locations[f.id].areas.some(a=>a.secret&&a.unlock>limit)){const seal=el('section','location-seal');seal.dataset.sealed='true';seal.append(el('span','','◇'),el('strong','','Mühürlü kayıt'),el('p','','İlgili kaynak alıntısına ulaşıldığında açılır.'));memory.append(seal);}
      if(area){const discoveries=(area.discoveries||[]).map(ref=>({ref,fact:data.facts.find(x=>x.id===ref.fact)})).filter(x=>x.fact&&Math.max(x.fact.unlock,x.ref.unlock||area.unlock)<=limit);if(discoveries.length){const layer=el('div','location-hotspots location-object-hotspots'),details=el('section','room-object-focus');memory.append(el('h4','','Kaynakta geçen nesneler'),details);for(const{ref,fact}of discoveries){const open=()=>{art.dispose(details);details.replaceChildren(el('small','','NESNE KAYDI'),el('h4','',fact.name),art.viewer(art.asset(fact),fact.name),el('blockquote','',fact.quote),el('p','',fact.chapter),button('İlk Kaydın Metnine Dön',()=>onRead(fact.unlock-fact.quote.length)));details.scrollIntoView({block:'nearest',behavior:art.quiet()?'instant':'smooth'});};const point=button('',open,'location-hotspot location-object-hotspot');point.dataset.roomFact=fact.id;point.style.left=ref.x+'%';point.style.top=ref.y+'%';point.setAttribute('aria-label',fact.name+' kaydını incele');point.append(art.icon(fact.id),el('span','',fact.name));layer.append(point);const row=button(fact.name+' · İncele',open,'world-button room-object-link');row.dataset.roomFact=fact.id;memory.insertBefore(row,details);}figure.addOverlay(layer);}}
      root.currentArea=area?.id||'';root.dispatchEvent(new CustomEvent('atlas:area',{bubbles:true,detail:{id:root.currentArea,name:area?.name||''}}));
    }
    async function go(id){if(busy||disposed)return;const area=id?areas.find(a=>a.id===id):null;if(id&&!area)return;if(area?.kind==='city'&&onNavigate){onNavigate(area);return;}const token=++generation;setBusy(true);status.textContent='Alan hazırlanıyor…';const image=art.photo(area?.src||outside,area?.name||f.name,'miniature-image');image.loading='eager';if(image.srcset)image.sizes='(max-width:600px) calc(100vw - 70px), 900px';pending=image;
      try{await Promise.race([image.decode(),new Promise((_,reject)=>{loadTimer=setTimeout(()=>reject(Error('image-timeout')),8000);})]);clearTimeout(loadTimer);if(disposed||token!==generation)return;
        if(art.quiet()){render(area,image);setBusy(false);return;}
        animation=surface.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(1.025)'}],{duration:180,fill:'forwards'});timer=setTimeout(()=>{if(disposed||token!==generation)return;animation?.cancel();render(area,image);animation=surface.animate([{opacity:0,transform:'translateY(4px) scale(.99)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:270});timer=setTimeout(()=>{setBusy(false);animation=null;},270);},180);
      }catch{if(!disposed&&token===generation){status.textContent='Bu alanın görseli yüklenemedi. Mevcut görünüm korundu.';selector.value=current?.id||'';setBusy(false);}}finally{clearTimeout(loadTimer);pending=null;}
    }
    root.dispose=()=>{disposed=true;generation++;clearTimeout(timer);clearTimeout(loadTimer);animation?.cancel();pending?.removeAttribute('src');pending?.removeAttribute('srcset');figure?.dispose?.();art.dispose(memory);};root.openArea=go;render(areas.find(a=>a.id===initialArea&&a.kind!=='city')||null);return root;
  }
  window.BookLocation=Object.freeze({has:id=>Boolean(data.locations?.[id]),create});
})();
